        return None
    g = b.grid
    s = 0.0
    s += {0: 0, 1: 1, 2: -1}[g[1][1]]
    s += {0: 0, 1: 1, 2: -0.5}[g[1][3]]
    if g[2][1] == 2:
        s -= 1
    if g[2][3] == 2:
        s -= 1.5
    if g[0][2] == 1:
        s += 0.5
    if b.ply < 6:
        s -= 1
    return s

def fires(b):
